def comps_of(arr,color):
    m=arr==color; lab=-np.ones(m.shape,dtype=int); n=0
    for i in range(m.shape[0]):
        for j in range(m.shape[1]):
            if m[i,j] and lab[i,j]<0:
                st=[(i,j)]; lab[i,j]=n
                while st:
                    a,b=st.pop()
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+di,b+dj
                        if 0<=x<m.shape[0] and 0<=y<m.shape[1] and m[x,y] and lab[x,y]<0:
                            lab[x,y]=n; st.append((x,y))
                n+=1
    return [(lab==i).nonzero()[0],(lab==i).nonzero()[1]]

