# Find maximal solid rectangles (rooms) per demo via exact cover greedy largest-first,
# then test center-mapping into output dims.
def maxrects(arr):
    ci=Counter(arr.flatten()); bgc=ci.most_common(1)[0][0]
    others=[c for c in ci if c!=bgc]
    blk=max(others,key=lambda c:ci[c])
    H,W=arr.shape; m=(arr==blk).astype(int); res=[]
    while m.any():
        best=None
        for r0 in range(H):
            for c0 in range(W):
                if not m[r0,c0]: continue
                for h in range(1,H-r0+1):
                    if not m[r0:r0+h,c0:c0+1].all(): break
                    for w in range(1,W-c0+1):
                        if m[r0:r0+h,c0:c0+w].all():
                            a=h*w
                            if best is None or a>best[0]:
                                best=(a,h,w,r0,c0)
        a,h,w,r0,c0=best
        res.append((r0,c0,h,w)); m[r0:r0+h,c0:c0+w]=0
    return res,bgc,blk

